// P5f lockstep: RTL (rtl/v2, tag rtl-v2-final) against its gate-level netlist (module renamed
// lfu_cache_controller_gl by tools/p5f_wrap.py; cell models generated by Yosys from the NanGate45
// liberty). Functional gate-level simulation, zero delay: no SDF, no timing.
// Same random stimulus as synthesis/p5b/tb_lockstep.sv. Every cycle after reset release, all
// outputs are compared with !== (an X or Z on either side counts as a mismatch): hit_flag,
// resp_valid, resp_data, fill_req, fill_addr. "miss" is resp_valid && !hit_flag (counted, and
// covered by comparing both signals). Every output of both designs is also checked for X/Z
// every cycle after reset release (XOR reduction === 1'bx; $isunknown gave false X reports in
// Icarus 12 once the progress display below was added, with every output bit 0 or 1).
`timescale 1ns / 1ps
module tb_gls_lockstep #(parameter COUNTER_MODE = 0, parameter CACHE_DEPTH = 256,
                         parameter CYCLES = 200000, parameter SEED = 1);
localparam AW = 20, VW = 128;
reg clk = 0, rst_n = 0;
always #0.5 clk = ~clk;
reg req_valid = 0, fill_valid = 0;
reg [AW-1:0] req_addr = 0;
reg [VW-1:0] fill_data = 0;
wire rv_r, hf_r, fr_r, rv_g, hf_g, fr_g;
wire [VW-1:0] rd_r, rd_g;
wire [AW-1:0] fa_r, fa_g;
lfu_cache_controller #(.CACHE_DEPTH(CACHE_DEPTH), .COUNTER_MODE(COUNTER_MODE)) rtl (
    .clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr),
    .resp_valid(rv_r), .resp_data(rd_r), .hit_flag(hf_r), .fill_req(fr_r), .fill_addr(fa_r),
    .fill_valid(fill_valid), .fill_data(fill_data));
lfu_cache_controller_gl gl (
    .clk(clk), .rst_n(rst_n), .req_valid(req_valid), .req_addr(req_addr),
    .resp_valid(rv_g), .resp_data(rd_g), .hit_flag(hf_g), .fill_req(fr_g), .fill_addr(fa_g),
    .fill_valid(fill_valid), .fill_data(fill_data));
integer cyc = 0, seed = SEED, pool, d;
integer m_hf = 0, m_rv = 0, m_rd = 0, m_fr = 0, m_fa = 0, mism = 0, x_g = 0, x_r = 0;
integer n_resp = 0, n_hit = 0, n_miss = 0, n_fill = 0;
function integer rnd(input integer unused);   // non-negative, advances seed
    rnd = $random(seed) & 32'h7fffffff;
endfunction
always @(posedge clk) if (rst_n) begin
    cyc = cyc + 1;
    if (hf_r !== hf_g) m_hf = m_hf + 1;
    if (rv_r !== rv_g) m_rv = m_rv + 1;
    if (rd_r !== rd_g) m_rd = m_rd + 1;
    if (fr_r !== fr_g) m_fr = m_fr + 1;
    if (fa_r !== fa_g) m_fa = m_fa + 1;
    if ({hf_r, rv_r, rd_r, fr_r, fa_r} !== {hf_g, rv_g, rd_g, fr_g, fa_g}) begin
        mism = mism + 1;
        if (mism <= 10) $display("MISMATCH cycle %0d: rtl hf=%b rv=%b fr=%b fa=%h rd=%h | gl hf=%b rv=%b fr=%b fa=%h rd=%h",
                                 cyc, hf_r, rv_r, fr_r, fa_r, rd_r, hf_g, rv_g, fr_g, fa_g, rd_g);
    end
    if ((^{hf_g, rv_g, rd_g, fr_g, fa_g}) === 1'bx) begin   // any X/Z bit makes the XOR reduction X
        x_g = x_g + 1;
        if (x_g <= 5) $display("X/Z ON NETLIST OUTPUT cycle %0d", cyc);
    end
    if ((^{hf_r, rv_r, rd_r, fr_r, fa_r}) === 1'bx) begin
        x_r = x_r + 1;
        if (x_r <= 5) $display("X/Z ON RTL OUTPUT cycle %0d", cyc);
    end
    if (rv_r) n_resp = n_resp + 1;
    if (rv_r && hf_r) n_hit = n_hit + 1;
    if (rv_r && !hf_r) n_miss = n_miss + 1;
    if (fr_r) n_fill = n_fill + 1;
    // progress, so a run stopped by the time limit still records how many cycles were compared
    if (cyc % 10000 == 0)
        begin $display("cycles compared %0d, mismatches %0d (x_cycles netlist %0d, rtl %0d)", cyc, mism, x_g, x_r); $fflush; end
end
// Stimulus on the falling edge, as in synthesis/p5b/tb_lockstep.sv.
initial begin
    repeat (3) @(negedge clk);
    rst_n = 1;
    while (cyc < CYCLES) begin
        @(negedge clk);
        pool = (rnd(0) % 4 == 0) ? 2 * CACHE_DEPTH : CACHE_DEPTH / 4 + 1;
        req_valid = (rnd(0) % 3) != 0;
        req_addr = 20'h40000 + (rnd(0) % pool);
        if (fr_r) begin
            d = rnd(0) % 4;
            req_valid = 0;
            repeat (d) @(negedge clk);
            fill_valid = 1; fill_data = {rnd(0), rnd(0), rnd(0), rnd(0)};
            @(negedge clk);
            fill_valid = 0;
        end
    end
    $display("gls_lockstep depth=%0d mode=%0d cycles=%0d responses=%0d hits=%0d misses=%0d fill_reqs=%0d mismatching_cycles=%0d hit_flag=%0d resp_valid=%0d resp_data=%0d fill_req=%0d fill_addr=%0d x_cycles_netlist=%0d x_cycles_rtl=%0d",
             CACHE_DEPTH, COUNTER_MODE, cyc, n_resp, n_hit, n_miss, n_fill, mism, m_hf, m_rv, m_rd, m_fr, m_fa, x_g, x_r);
    if (mism == 0 && x_g == 0 && x_r == 0 && n_hit > 0 && n_miss > 0) $display("GLS LOCKSTEP PASSED");
    else                                                              $display("GLS LOCKSTEP FAILED");
    $finish;
end
endmodule
